-- Tahap 5.1–5.3: local-session verified exam operations.
SET LOCAL ROLE sim_guru_owner;
CREATE TABLE app.exam_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),academic_period_id uuid NOT NULL REFERENCES app.academic_periods(id),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 120),date_start date NOT NULL,date_end date NOT NULL,default_committee_jtm numeric(12,4) NOT NULL CHECK(default_committee_jtm>0),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,CHECK(date_end-date_start BETWEEN 0 AND 365));
CREATE TABLE app.exam_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_id uuid NOT NULL REFERENCES app.exam_periods(id),date date NOT NULL,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 120),time_start time NOT NULL,time_end time NOT NULL,scheduled_jtm numeric(12,4) NOT NULL CHECK(scheduled_jtm>0),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,CHECK(time_end>time_start));
CREATE INDEX exam_sessions_period ON app.exam_sessions(period_id,date);
CREATE TABLE app.exam_rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES app.exam_sessions(id),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 120),subject_id uuid NOT NULL REFERENCES app.subjects(id),total_students int NOT NULL CHECK(total_students BETWEEN 0 AND 1000),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX exam_room_name ON app.exam_rooms(session_id,lower(name)) WHERE active;
CREATE TABLE app.exam_room_classes(exam_room_id uuid NOT NULL REFERENCES app.exam_rooms(id),class_id uuid NOT NULL REFERENCES app.classes(id),PRIMARY KEY(exam_room_id,class_id));
CREATE INDEX exam_room_class ON app.exam_room_classes(class_id);
CREATE TABLE app.exam_supervisor_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_room_id uuid NOT NULL REFERENCES app.exam_rooms(id),user_id uuid NOT NULL REFERENCES app.app_users(id),override_jtm numeric(12,4) CHECK(override_jtm>0),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1);
CREATE INDEX exam_supervisor_room ON app.exam_supervisor_assignments(exam_room_id);
CREATE TABLE app.exam_committee_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_id uuid NOT NULL REFERENCES app.exam_periods(id),date date NOT NULL,user_id uuid NOT NULL REFERENCES app.app_users(id),scheduled_jtm numeric(12,4) NOT NULL CHECK(scheduled_jtm>0),exclusive_time_start time,exclusive_time_end time,active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,CHECK((exclusive_time_start IS NULL AND exclusive_time_end IS NULL) OR(exclusive_time_start IS NOT NULL AND exclusive_time_end>exclusive_time_start)));
CREATE INDEX exam_committee_period ON app.exam_committee_assignments(period_id,date);
CREATE TABLE app.exam_baps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid NOT NULL REFERENCES app.activity_occurrences(id),assignment_id uuid NOT NULL REFERENCES app.activity_assignments(id),user_id uuid NOT NULL REFERENCES app.app_users(id),present int NOT NULL CHECK(present>=0),absent int NOT NULL CHECK(absent>=0),notes text NOT NULL CHECK(length(notes)<=1000),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','locked')),submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),version bigint NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX exam_bap_active ON app.exam_baps(occurrence_id) WHERE state='active';
CREATE INDEX exam_bap_owner ON app.exam_baps(user_id,submitted_at);
CREATE TABLE ops.module_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES app.app_users(id),request jsonb NOT NULL,fingerprint text NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes',consumed_at timestamptz);
ALTER TABLE app.activity_occurrences DROP CONSTRAINT occurrence_kind,DROP CONSTRAINT occurrence_source;
ALTER TABLE app.activity_occurrences ADD COLUMN exam_supervisor_id uuid UNIQUE REFERENCES app.exam_supervisor_assignments(id),ADD COLUMN exam_committee_id uuid UNIQUE REFERENCES app.exam_committee_assignments(id),ADD COLUMN removed_at timestamptz,
ADD CONSTRAINT occurrence_kind CHECK(kind IN('KBM','PIKET','UPACARA','EXAM_SUPERVISOR','EXAM_COMMITTEE')),
ADD CONSTRAINT occurrence_source CHECK((kind='KBM' AND schedule_id IS NOT NULL AND duty_schedule_id IS NULL AND exam_supervisor_id IS NULL AND exam_committee_id IS NULL AND class_id IS NOT NULL AND subject_id IS NOT NULL) OR(kind IN('PIKET','UPACARA') AND schedule_id IS NULL AND duty_schedule_id IS NOT NULL AND exam_supervisor_id IS NULL AND exam_committee_id IS NULL AND class_id IS NULL AND subject_id IS NULL) OR(kind='EXAM_SUPERVISOR' AND schedule_id IS NULL AND duty_schedule_id IS NULL AND exam_supervisor_id IS NOT NULL AND exam_committee_id IS NULL AND class_id IS NULL AND subject_id IS NOT NULL) OR(kind='EXAM_COMMITTEE' AND schedule_id IS NULL AND duty_schedule_id IS NULL AND exam_supervisor_id IS NULL AND exam_committee_id IS NOT NULL AND class_id IS NULL AND subject_id IS NULL));
ALTER TABLE finance.jtm_ledger DROP CONSTRAINT ledger_source_kind;
ALTER TABLE finance.jtm_ledger ADD CONSTRAINT ledger_source_kind CHECK(source_kind IN('KBM','PIKET','UPACARA','EXAM_SUPERVISOR','EXAM_COMMITTEE','PARTIAL_SUB_KBM','PARTIAL_SUB_PIKET','PARTIAL_SUB_EXAM','REVERSAL'));
CREATE UNIQUE INDEX ledger_exam_revision ON finance.jtm_ledger(assignment_id,revision,source_kind) WHERE source_kind IN('EXAM_SUPERVISOR','EXAM_COMMITTEE');
CREATE UNIQUE INDEX ledger_exam_allocation ON finance.jtm_ledger(allocation_id,revision,source_kind) WHERE source_kind='PARTIAL_SUB_EXAM';
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['app.exam_periods','app.exam_sessions','app.exam_rooms','app.exam_room_classes','app.exam_supervisor_assignments','app.exam_committee_assignments','app.exam_baps','ops.module_previews'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY owner_internal ON %s TO sim_guru_owner USING(true) WITH CHECK(true)',t);EXECUTE format('REVOKE ALL ON %s FROM PUBLIC,sim_guru_business,sim_guru_auth,sim_guru_worker',t);END LOOP;END $$;
CREATE OR REPLACE FUNCTION app.schedule_dependencies() RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN IF to_regclass('finance.honor_periods') IS NOT NULL THEN RAISE EXCEPTION 'CONTEXT_DEPENDENCY_UNAVAILABLE' USING ERRCODE='55000';END IF;END $$;
CREATE OR REPLACE FUNCTION app.calendar_dependencies(p_date date) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN PERFORM app.schedule_dependencies();RETURN (SELECT jsonb_build_object('assignmentIntegration','exams_ready','activeExamPeriods',coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'academicPeriodId',academic_period_id) ORDER BY id),'[]'),'activeExamPeriodIds',coalesce(jsonb_agg(id ORDER BY id),'[]')) FROM app.exam_periods WHERE active AND p_date BETWEEN date_start AND date_end);END $$;
CREATE FUNCTION app.exam_period_for(p_occ uuid) RETURNS uuid LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT coalesce(s.period_id,c.period_id) FROM app.activity_occurrences o LEFT JOIN app.exam_supervisor_assignments v ON v.id=o.exam_supervisor_id LEFT JOIN app.exam_rooms r ON r.id=v.exam_room_id LEFT JOIN app.exam_sessions s ON s.id=r.session_id LEFT JOIN app.exam_committee_assignments c ON c.id=o.exam_committee_id WHERE o.id=p_occ $$;
CREATE FUNCTION app.is_committee(p_user uuid,p_date date,p_period uuid DEFAULT NULL,p_timein boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN app.activity_assignments a ON a.occurrence_id=o.id JOIN app.activity_confirmations c ON c.assignment_id=a.id AND c.revoked_at IS NULL WHERE o.kind='EXAM_COMMITTEE' AND o.removed_at IS NULL AND o.date=p_date AND a.effective_user_id=p_user AND(p_period IS NULL OR app.exam_period_for(o.id)=p_period)) AND(NOT p_timein OR EXISTS(SELECT 1 FROM app.daily_attendance WHERE user_id=p_user AND date=p_date AND actual_time_in IS NOT NULL AND time_in_source='admin')) $$;
CREATE FUNCTION app.exam_required(p_date date,p_period uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'expectedStudents',c.expected_students,'complete',EXISTS(SELECT 1 FROM app.student_attendance a WHERE a.class_id=c.id AND a.date=p_date AND a.academic_period_id=c.academic_period_id)) ORDER BY c.name,c.id),'[]') FROM app.classes c WHERE c.archived_at IS NULL AND EXISTS(SELECT 1 FROM app.exam_room_classes rc JOIN app.exam_rooms r ON r.id=rc.exam_room_id JOIN app.exam_sessions s ON s.id=r.session_id JOIN app.exam_periods p ON p.id=s.period_id WHERE rc.class_id=c.id AND r.active AND s.active AND p.active AND s.date=p_date AND(p_period IS NULL OR p.id=p_period)) $$;
ALTER FUNCTION app.duty_permission(uuid,uuid,text) RENAME TO stage4_duty_permission;
CREATE FUNCTION app.duty_permission(p_actor uuid,p_occurrence uuid,p_operation text) RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE o app.activity_occurrences%ROWTYPE;a app.activity_assignments%ROWTYPE;BEGIN SELECT * INTO o FROM app.activity_occurrences WHERE id=p_occurrence;IF o.kind NOT IN('EXAM_SUPERVISOR','EXAM_COMMITTEE') THEN PERFORM app.stage4_duty_permission(p_actor,p_occurrence,p_operation);RETURN;END IF;
SELECT * INTO a FROM app.activity_assignments WHERE occurrence_id=o.id;IF o.removed_at IS NOT NULL OR NOT coalesce((app.day_context_internal(o.date)->>'examEnabled')::boolean,false) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;IF o.date<>app.activity_today() THEN RAISE EXCEPTION 'TODAY_ONLY' USING ERRCODE='42501';END IF;
IF NOT app.actor_is_admin() THEN IF o.kind='EXAM_COMMITTEE' OR NOT app.is_committee(p_actor,o.date,app.exam_period_for(o.id)) OR p_actor IN(a.effective_user_id,a.original_user_id) THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(app.exam_required(o.date,app.exam_period_for(o.id))) x WHERE NOT(x->>'complete')::boolean) THEN RAISE EXCEPTION 'STUDENT_ATTENDANCE_MISMATCH' USING ERRCODE='42501';END IF;END IF;
IF p_operation NOT IN('confirm','revoke') AND p_actor IN(a.effective_user_id,a.original_user_id) THEN RAISE EXCEPTION 'SELF_OPERATION_FORBIDDEN' USING ERRCODE='42501';END IF;IF p_operation IN('adjust','allocate','remove-allocation','reset') AND o.kind<>'EXAM_SUPERVISOR' THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';END IF;END $$;
ALTER FUNCTION app.duty_candidate(uuid,uuid) RENAME TO stage4_duty_candidate;
DO $patch$ DECLARE fn regprocedure:='app.stage4_duty_candidate(uuid,uuid)'::regprocedure;b text;BEGIN SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,' IF EXISTS(SELECT 1 FROM app.teaching_schedules',' IF coalesce((app.day_context_internal(o.date)->>''kbmEnabled'')::boolean,false) AND(EXISTS(SELECT 1 FROM app.teaching_schedules');b:=replace(b,') THEN RAISE EXCEPTION ''DUTY_COLLISION'' USING ERRCODE=''23505'';END IF;END ', ')) THEN RAISE EXCEPTION ''DUTY_COLLISION'' USING ERRCODE=''23505'';END IF;END ');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);END $patch$;

CREATE FUNCTION app.duty_candidate(p_user uuid,p_occurrence uuid) RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE o app.activity_occurrences%ROWTYPE;sid uuid;BEGIN SELECT * INTO o FROM app.activity_occurrences WHERE id=p_occurrence;IF o.kind='EXAM_COMMITTEE' AND EXISTS(SELECT 1 FROM app.exam_committee_assignments WHERE id=o.exam_committee_id AND exclusive_time_start IS NULL) THEN IF NOT EXISTS(SELECT 1 FROM app.app_users WHERE id=p_user AND role='guru' AND status='active') THEN RAISE EXCEPTION 'SUBSTITUTE_INVALID' USING ERRCODE='22023';END IF;ELSE PERFORM app.stage4_duty_candidate(p_user,p_occurrence);END IF;
SELECT r.session_id INTO sid FROM app.exam_supervisor_assignments v JOIN app.exam_rooms r ON r.id=v.exam_room_id WHERE v.id=o.exam_supervisor_id;
IF EXISTS(SELECT 1 FROM app.activity_occurrences q JOIN app.activity_assignments a ON a.occurrence_id=q.id LEFT JOIN app.exam_supervisor_assignments v ON v.id=q.exam_supervisor_id LEFT JOIN app.exam_rooms r ON r.id=v.exam_room_id LEFT JOIN app.exam_committee_assignments c ON c.id=q.exam_committee_id WHERE q.id<>o.id AND q.removed_at IS NULL AND q.date=o.date AND a.effective_user_id=p_user AND((o.kind='EXAM_COMMITTEE' AND q.kind='EXAM_COMMITTEE') OR(sid IS NOT NULL AND r.session_id=sid) OR(q.kind='EXAM_SUPERVISOR' AND o.kind<>'PIKET' AND NOT(o.kind='EXAM_COMMITTEE' AND EXISTS(SELECT 1 FROM app.exam_committee_assignments WHERE id=o.exam_committee_id AND exclusive_time_start IS NULL)) AND q.time_start<o.time_end AND q.time_end>o.time_start) OR(q.kind='EXAM_COMMITTEE' AND c.exclusive_time_start IS NOT NULL AND o.kind<>'PIKET' AND NOT(o.kind='EXAM_COMMITTEE' AND EXISTS(SELECT 1 FROM app.exam_committee_assignments WHERE id=o.exam_committee_id AND exclusive_time_start IS NULL)) AND c.exclusive_time_start<o.time_end AND c.exclusive_time_end>o.time_start))) OR EXISTS(SELECT 1 FROM finance.jtm_allocations r JOIN app.activity_occurrences q ON q.id=r.occurrence_id WHERE q.id<>o.id AND q.kind='EXAM_SUPERVISOR' AND q.removed_at IS NULL AND q.date=o.date AND r.cancelled_at IS NULL AND r.user_id=p_user AND o.kind<>'PIKET' AND NOT(o.kind='EXAM_COMMITTEE' AND EXISTS(SELECT 1 FROM app.exam_committee_assignments WHERE id=o.exam_committee_id AND exclusive_time_start IS NULL)) AND q.time_start<o.time_end AND q.time_end>o.time_start) THEN RAISE EXCEPTION 'DUTY_COLLISION' USING ERRCODE='23505';END IF;END $$;
-- Existing trigger wrapper delegates legacy validation through its original body.
DO $patch$ DECLARE fn regprocedure:='finance.ledger_integrity()'::regprocedure;b text;needle text:=' IF NEW.source_kind=''KBM'' THEN';BEGIN SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;IF length(b)-length(replace(b,needle,''))<>length(needle) THEN RAISE EXCEPTION 'PRIOR_ROUTINE_MISMATCH';END IF;
b:=replace(b,needle,$new$ IF NEW.source_kind IN('EXAM_SUPERVISOR','EXAM_COMMITTEE','PARTIAL_SUB_EXAM') THEN
IF o.removed_at IS NOT NULL OR NEW.assignment_id IS DISTINCT FROM a.id OR NEW.revision<>a.version OR NEW.journal_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM app.activity_confirmations WHERE assignment_id=a.id AND revoked_at IS NULL) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
IF NEW.source_kind='PARTIAL_SUB_EXAM' THEN SELECT * INTO r FROM finance.jtm_allocations WHERE id=NEW.allocation_id;IF o.kind<>'EXAM_SUPERVISOR' OR r.id IS NULL OR r.cancelled_at IS NOT NULL OR r.occurrence_id<>o.id OR NEW.user_id<>r.user_id OR NEW.jtm<>r.allocated_jtm THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
ELSE IF NEW.source_kind<>o.kind OR NEW.user_id<>a.effective_user_id OR NEW.jtm<>app.jtm_basis(o.id) OR NEW.allocation_id IS NOT NULL OR(o.kind='EXAM_SUPERVISOR' AND NOT EXISTS(SELECT 1 FROM app.exam_baps WHERE occurrence_id=o.id AND state='active' AND user_id=a.effective_user_id AND assignment_id=a.id)) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;END IF;RETURN NEW;END IF;
 IF NEW.source_kind='KBM' THEN$new$);EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);END $patch$;
ALTER FUNCTION finance.reconcile_occurrence(uuid) RENAME TO stage4_reconcile_occurrence;
CREATE FUNCTION finance.reconcile_occurrence(p_occurrence uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE o app.activity_occurrences%ROWTYPE;a app.activity_assignments%ROWTYPE;BEGIN SELECT * INTO o FROM app.activity_occurrences WHERE id=p_occurrence;IF o.kind NOT IN('EXAM_SUPERVISOR','EXAM_COMMITTEE') THEN PERFORM finance.stage4_reconcile_occurrence(p_occurrence);RETURN;END IF;SELECT * INTO a FROM app.activity_assignments WHERE occurrence_id=o.id;PERFORM finance.reverse_occurrence(o.id);
IF o.removed_at IS NULL AND EXISTS(SELECT 1 FROM app.activity_confirmations WHERE assignment_id=a.id AND revoked_at IS NULL) THEN
IF o.kind='EXAM_COMMITTEE' OR EXISTS(SELECT 1 FROM app.exam_baps WHERE occurrence_id=o.id AND user_id=a.effective_user_id AND state='active') THEN INSERT INTO finance.jtm_ledger(source_kind,occurrence_id,user_id,date,jtm,revision,assignment_id) VALUES(o.kind,o.id,a.effective_user_id,o.date,app.jtm_basis(o.id),a.version,a.id);END IF;
INSERT INTO finance.jtm_ledger(source_kind,occurrence_id,user_id,date,jtm,revision,assignment_id,allocation_id) SELECT 'PARTIAL_SUB_EXAM',o.id,r.user_id,o.date,r.allocated_jtm,a.version,a.id,r.id FROM finance.jtm_allocations r WHERE r.occurrence_id=o.id AND r.cancelled_at IS NULL;END IF;END $$;
ALTER FUNCTION app.duty_cleanup(uuid,uuid) RENAME TO stage4_duty_cleanup;
CREATE FUNCTION app.duty_cleanup(p_occurrence uuid,p_actor uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN PERFORM app.stage4_duty_cleanup(p_occurrence,p_actor);UPDATE app.exam_baps SET state='locked',version=version+1,updated_at=clock_timestamp() WHERE occurrence_id=p_occurrence AND state='active';END $$;
ALTER FUNCTION app.duty_fingerprint(uuid) RENAME TO stage4_duty_fingerprint;
CREATE FUNCTION app.duty_fingerprint(p_occurrence uuid) RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT md5(jsonb_build_array(app.stage4_duty_fingerprint(p_occurrence),(SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM app.exam_baps b WHERE occurrence_id=p_occurrence))::text) $$;
ALTER FUNCTION app.duty_preview(text,jsonb) RENAME TO stage4_duty_preview;
REVOKE ALL ON FUNCTION app.stage4_duty_preview(text,jsonb) FROM PUBLIC,sim_guru_business;
CREATE FUNCTION app.duty_preview(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result jsonb;BEGIN result:=app.stage4_duty_preview(p_session,p_data);RETURN result||jsonb_build_object('activeBaps',(SELECT count(*) FROM app.exam_baps WHERE occurrence_id=(p_data->>'occurrenceId')::uuid AND state='active'));END $$;
CREATE FUNCTION app.exam_now() RETURNS timestamp LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$ SELECT clock_timestamp() AT TIME ZONE 'Asia/Jakarta' $$;
CREATE FUNCTION app.exam_bap_save(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;o app.activity_occurrences%ROWTYPE;a app.activity_assignments%ROWTYPE;p app.exam_periods%ROWTYPE;b app.exam_baps%ROWTYPE;h int:=(p_data->>'present')::int;n int:=(p_data->>'absent')::int;old jsonb;BEGIN
actor:=app.activity_guard(p_session,true);SELECT * INTO o FROM app.activity_occurrences WHERE id=(p_data->>'occurrenceId')::uuid AND kind='EXAM_SUPERVISOR' AND removed_at IS NULL;SELECT * INTO a FROM app.activity_assignments WHERE occurrence_id=o.id FOR UPDATE;SELECT * INTO p FROM app.exam_periods WHERE id=app.exam_period_for(o.id) AND active;
IF o.id IS NULL OR p.id IS NULL OR a.effective_user_id<>actor THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;
IF app.activity_today()<o.date THEN RAISE EXCEPTION 'FUTURE_DATE' USING ERRCODE='42501';END IF;IF app.activity_today()>p.date_end THEN RAISE EXCEPTION 'DATE_EXPIRED' USING ERRCODE='42501';END IF;IF app.activity_today()=o.date AND app.exam_now()<o.date+o.time_end+interval '5 minutes' THEN RAISE EXCEPTION 'ATTENDANCE_TIME_INVALID' USING ERRCODE='42501';END IF;
IF NOT EXISTS(SELECT 1 FROM app.activity_confirmations WHERE assignment_id=a.id AND revoked_at IS NULL) THEN RAISE EXCEPTION 'NO_ACTIVE_CONFIRMATION' USING ERRCODE='42501';END IF;PERFORM finance.guard_open(o.date);
IF h IS NULL OR n IS NULL OR least(h,n)<0 OR h+n>1000 OR(o.expected_students>0 AND h+n<>o.expected_students) OR p_data->>'notes' IS NULL OR length(p_data->>'notes')>1000 THEN RAISE EXCEPTION 'STUDENT_COUNT_MISMATCH' USING ERRCODE='22023';END IF;
SELECT * INTO b FROM app.exam_baps WHERE occurrence_id=o.id AND state='active' FOR UPDATE;old:=to_jsonb(b);
IF p_data->>'operation'='create' THEN IF b.id IS NOT NULL THEN RAISE EXCEPTION 'DUPLICATE_JOURNAL' USING ERRCODE='23505';END IF;IF p_data->>'version'<>'0' THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;INSERT INTO app.exam_baps(occurrence_id,assignment_id,user_id,present,absent,notes) VALUES(o.id,a.id,actor,h,n,p_data->>'notes') RETURNING * INTO b;
ELSIF p_data->>'operation'='edit' THEN IF b.id IS NULL OR b.user_id<>actor OR b.version IS DISTINCT FROM(p_data->>'version')::bigint THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;UPDATE app.exam_baps SET present=h,absent=n,notes=p_data->>'notes',version=version+1,updated_at=clock_timestamp() WHERE id=b.id RETURNING * INTO b;ELSE RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
UPDATE app.activity_assignments SET version=version+1 WHERE id=a.id;PERFORM finance.reconcile_occurrence(o.id);PERFORM app.activity_audit('exam-bap-'||(p_data->>'operation'),b.id,'Berita acara ujian',old,to_jsonb(b));RETURN to_jsonb(b)||jsonb_build_object('version',b.version::text);END $$;
-- All master writes use the same global write lock as schedules and operations.

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app,finance FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.exam_bap_save(text,jsonb),app.duty_preview(text,jsonb) TO sim_guru_business;
RESET ROLE;
